-- seed_demo_cleanup.sql
-- Removes ONLY demo rows from seed_demo.sql (demo-vendor-%@eme.demo + fixed ids).
-- Safe to run many times. No TRUNCATE. Does not touch rls-%@eme.test data.

begin;

delete from public.cart_items
where product_id in (
  select id from public.products
  where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010') or slug like 'demo-%'
);

delete from public.wishlist_items
where product_id in (
  select id from public.products
  where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010') or slug like 'demo-%'
);

delete from public.product_reviews
where product_id in (
  select id from public.products
  where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010') or slug like 'demo-%'
);

delete from public.reel_likes
where reel_id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030';
delete from public.reel_saves
where reel_id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030';
delete from public.reel_comments
where reel_id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030';

delete from public.reel_products
where reel_id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030'
   or product_id in (select id from public.products where vendor_id in (
    'd1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010'
   ) or slug like 'demo-%');

delete from public.live_messages
where stream_id between 'd7777777-d777-4777-8777-000000000001' and 'd7777777-d777-4777-8777-000000000002';

delete from public.live_stream_products
where stream_id between 'd7777777-d777-4777-8777-000000000001' and 'd7777777-d777-4777-8777-000000000002'
   or product_id in (select id from public.products where vendor_id in (
    'd1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010'
   ) or slug like 'demo-%');

update public.live_streams set pinned_product_id = null
where pinned_product_id in (
  select id from public.products
  where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010') or slug like 'demo-%'
);

delete from public.live_streams
where id between 'd7777777-d777-4777-8777-000000000001' and 'd7777777-d777-4777-8777-000000000002'
   or vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010');

delete from public.reels
where id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030'
   or vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010');

delete from public.product_images
where product_id in (
  select id from public.products
  where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010') or slug like 'demo-%'
) or id between 'd3333333-d333-4333-8333-000000000001' and 'd3333333-d333-4333-8333-000000000525';

delete from public.products
where vendor_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010')
   or id between 'd2222222-d222-4222-8222-000000000001' and 'd2222222-d222-4222-8222-000000000150'
   or slug like 'demo-%';

delete from public.vendor_profiles
where profile_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010')
   or slug in (
  'demo-purush-lane',
  'demo-nari-atelier',
  'demo-gadget-bazar',
  'demo-case-corner',
  'demo-ghor-o-ranna',
  'demo-rupchaya-beauty',
  'demo-bazaar-basket',
  'demo-boighar',
  'demo-khelaghar',
  'demo-choto-bondhu'
);

-- Demo-only categories (children first). Does not delete seed.sql 11111111-... rows.
delete from public.categories
where id between 'd4444444-d444-4444-8444-000000000011' and 'd4444444-d444-4444-8444-000000000083';
delete from public.categories
where id between 'd4444444-d444-4444-8444-000000000001' and 'd4444444-d444-4444-8444-000000000008';

delete from auth.identities
where user_id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010')
   or user_id in (select id from auth.users where email like 'demo-vendor-%@eme.demo');

delete from auth.users
where id in ('d1111111-d111-4111-8111-000000000001',
    'd1111111-d111-4111-8111-000000000002',
    'd1111111-d111-4111-8111-000000000003',
    'd1111111-d111-4111-8111-000000000004',
    'd1111111-d111-4111-8111-000000000005',
    'd1111111-d111-4111-8111-000000000006',
    'd1111111-d111-4111-8111-000000000007',
    'd1111111-d111-4111-8111-000000000008',
    'd1111111-d111-4111-8111-000000000009',
    'd1111111-d111-4111-8111-000000000010')
   or email like 'demo-vendor-%@eme.demo';

commit;

select
  (select count(*) from auth.users where email like 'demo-vendor-%@eme.demo') as leftover_auth_users,
  (select count(*) from public.profiles where id between 'd1111111-d111-4111-8111-000000000001' and 'd1111111-d111-4111-8111-000000000010') as leftover_profiles,
  (select count(*) from public.vendor_profiles where profile_id between 'd1111111-d111-4111-8111-000000000001' and 'd1111111-d111-4111-8111-000000000010' or slug like 'demo-%') as leftover_shops,
  (select count(*) from public.products where id between 'd2222222-d222-4222-8222-000000000001' and 'd2222222-d222-4222-8222-000000000150' or slug like 'demo-%') as leftover_products,
  (select count(*) from public.product_images where id between 'd3333333-d333-4333-8333-000000000001' and 'd3333333-d333-4333-8333-000000000525') as leftover_images,
  (select count(*) from public.reels where id between 'd5555555-d555-4555-8555-000000000001' and 'd5555555-d555-4555-8555-000000000030') as leftover_reels,
  (select count(*) from public.reel_products where id between 'd6666666-d666-4666-8666-000000000001' and 'd6666666-d666-4666-8666-000000000060') as leftover_reel_links,
  (select count(*) from public.live_streams where id between 'd7777777-d777-4777-8777-000000000001' and 'd7777777-d777-4777-8777-000000000002') as leftover_lives,
  (select count(*) from public.categories where id::text like 'd4444444-%') as leftover_demo_categories;
